grants.statement:
grant insert(
  kind,title,body,category,location,location_latitude,location_longitude,
  location_precision,price,image_path
) on public.posts to authenticated;

grant update(
  title,body,category,location,location_latitude,location_longitude,
  location_precision,price,image_path
) on public.posts to authenticated;

revoke all on function public.list_map_missions(double precision,double precision,
  double precision,double precision,text,text,timestamptz,timestamptz,
  double precision,double precision,double precision) from public,anon,authenticated;

grant execute on function public.list_map_missions(double precision,double precision,
  double precision,double precision,text,text,timestamptz,timestamptz,
  double precision,double precision,double precision) to authenticated;

policies.statement:
create policy "Users can update their profile"
  on public.profiles
  for update
  to authenticated
  using ((select auth.uid()) = id)
  with check ((select auth.uid()) = id);

create policy "Live stories" on public.stories for select to authenticated using(
 deleted_at is null and expires_at>now() and (not hidden or public.community_is_admin())
 and public.showcase_owner_visible(author_id));
